import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.DYPTBNgj.js";const f=JSON.parse('{"title":"ZFS property reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/properties.md","filePath":"reference/properties.md","lastUpdated":null}'),r={name:"reference/properties.md"};function a(n,e,i,s,p,l){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="zfs-property-reference" tabindex="-1">ZFS property reference <a class="header-anchor" href="#zfs-property-reference" aria-label="Permalink to &quot;ZFS property reference&quot;">​</a></h1><p>All public names begin with <code>org.boomerangz:</code>. Values configured locally on a dataset can be inherited by its descendants. Received copies do not activate a destination or control its policy.</p><table tabindex="0"><thead><tr><th>Suffix</th><th>Default</th><th>Valid values</th><th>Effect</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>off</code></td><td><code>on</code>, <code>off</code></td><td>Enable or mask management.</td></tr><tr><td><code>remote</code></td><td>Unset</td><td>Comma-separated configured remote names</td><td>Select network destinations.</td></tr><tr><td><code>local</code></td><td>Unset</td><td>Comma-separated ZFS dataset names</td><td>Select destinations on this host.</td></tr><tr><td><code>policy</code></td><td><code>12x5m,24x1h,14x1d</code></td><td>Positive grid tiers using <code>m</code>, <code>h</code>, <code>d</code>, <code>w</code>, <code>mo</code>, or <code>y</code></td><td>Set snapshot cadence and retention.</td></tr><tr><td><code>large_blocks</code></td><td><code>on</code></td><td><code>on</code>, <code>off</code></td><td>Preserve large blocks when supported by the receiver.</td></tr><tr><td><code>compressed</code></td><td><code>on</code></td><td><code>on</code>, <code>off</code></td><td>Send compressed blocks.</td></tr><tr><td><code>raw</code></td><td>Encryption-dependent</td><td><code>on</code>, <code>off</code></td><td>Send encrypted data without decrypting it for transfer.</td></tr><tr><td><code>props</code></td><td><code>off</code></td><td><code>on</code>, <code>off</code></td><td>Carry dataset properties while excluding Boomerangz policy from the receive.</td></tr><tr><td><code>incremental</code></td><td><code>all</code></td><td><code>all</code>, <code>latest</code></td><td>Include intermediate snapshots or send directly from the common base.</td></tr><tr><td><code>replicate</code></td><td><code>off</code></td><td><code>on</code>, <code>off</code></td><td>Replicate the complete descendant package.</td></tr><tr><td><code>discard</code></td><td><code>off</code></td><td><code>off</code>, <code>first</code>, <code>all</code></td><td>Disable path rewriting, append the source path without its pool component, or append only the final component.</td></tr><tr><td><code>set_prop:NAME</code></td><td>Unset</td><td>Native ZFS property value</td><td>Set a property on receive.</td></tr><tr><td><code>ignore_prop:NAME</code></td><td>Unset</td><td><code>on</code>, <code>off</code></td><td>Exclude an incoming property; <code>off</code> masks an inherited exclusion.</td></tr></tbody></table><p>A matching <code>set_prop</code> takes precedence over <code>ignore_prop</code> and produces a warning. Neither dynamic form may target an <code>org.boomerangz:*</code> property.</p><h2 id="receive-path-mapping" tabindex="-1">Receive path mapping <a class="header-anchor" href="#receive-path-mapping" aria-label="Permalink to &quot;Receive path mapping&quot;">​</a></h2><p>Given source <code>tank/projects/code</code> and destination root <code>backup/archive</code>:</p><table tabindex="0"><thead><tr><th><code>discard</code></th><th>Result</th></tr></thead><tbody><tr><td><code>off</code> (default)</td><td><code>backup/archive</code></td></tr><tr><td><code>first</code></td><td><code>backup/archive/projects/code</code></td></tr><tr><td><code>all</code></td><td><code>backup/archive/code</code></td></tr></tbody></table><p><code>off</code> means that Boomerangz passes no <code>-d</code> or <code>-e</code> path-mapping option to <code>zfs receive</code>; the configured destination is therefore the exact receive root. It does not append the complete source name. Descendants of a recursive stream are preserved relative to that root.</p><p>Preview and verify mappings before the first transfer. Boomerangz binds a source to the verified destination identity; replacing a pool or dataset with the same name does not silently authorize the replacement.</p><h2 id="reserved-state" tabindex="-1">Reserved state <a class="header-anchor" href="#reserved-state" aria-label="Permalink to &quot;Reserved state&quot;">​</a></h2><p>Properties beginning with <code>org.boomerangz:state:</code> are managed recovery and ownership records. Do not create, copy, or edit them manually. Use <code>dataset adopt</code>, <code>dataset clean</code>, or <code>identity recover</code> when an administrative transition is required.</p>',11)])])}const m=t(r,[["render",a]]);export{f as __pageData,m as default};
